import { ESTADOS, PALETA_CATEGORICA, resuelvePaleta, coloresCategorias, estadosTopoJSON, CENTROIDES_ESTADOS, MOSAICO_ESTADOS, interpolaPaleta, MOSAICO_COLUMNAS, MOSAICO_FILAS } from './chunk-BCKBK4SR.js';
import { geoMercator, geoPath } from 'd3-geo';
import { feature } from 'topojson-client';

var PORCVE = new Map(ESTADOS.map((e) => [e.cve, e]));
var ESCAPES = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;"
};
var esc = (s) => s.replace(/[&<>"]/g, (c) => ESCAPES[c]);
function mapaSVG(opts = {}) {
  const {
    data,
    categorias,
    paleta,
    colorRange,
    paletaCategorica = PALETA_CATEGORICA,
    emptyColor = "#e5e7eb",
    stroke = "#ffffff",
    strokeWidth = 0.6,
    width = 800,
    height = 600,
    background,
    etiquetas,
    colorEtiqueta = "#334155",
    fontSize = 9,
    titulo = "Mapa de M\xE9xico por estados"
  } = opts;
  const cols = resuelvePaleta(paleta, colorRange);
  const colorCat = categorias ? coloresCategorias(categorias, paletaCategorica) : null;
  const fc = feature(
    estadosTopoJSON,
    estadosTopoJSON.objects.estados
  );
  const projection = geoMercator().fitExtent(
    [
      [12, 12],
      [width - 12, height - 12]
    ],
    fc
  );
  const path = geoPath(projection);
  const vals = data ? Object.values(data).filter((v) => Number.isFinite(v)) : [];
  const min = vals.length ? Math.min(...vals) : 0;
  const max = vals.length ? Math.max(...vals) : 0;
  const fill = (cve) => {
    if (colorCat) {
      const c = categorias?.[cve];
      return (c != null ? colorCat.get(c) : void 0) ?? emptyColor;
    }
    const v = data?.[cve];
    if (v == null || !Number.isFinite(v)) return emptyColor;
    const t = max > min ? (v - min) / (max - min) : 1;
    return interpolaPaleta(cols, t);
  };
  const paths = fc.features.map(
    (f) => `<path d="${path(f) ?? ""}" fill="${fill(f.properties.cve)}" stroke="${stroke}" stroke-width="${strokeWidth}" data-cve="${esc(f.properties.cve)}" data-nombre="${esc(f.properties.nombre)}"/>`
  ).join("");
  let labels = "";
  if (etiquetas) {
    const texto = (e) => typeof etiquetas === "function" ? etiquetas(e) : etiquetas === "nombre" ? e.nombreCorto : e.abreviatura;
    labels = Object.entries(CENTROIDES_ESTADOS).map(([cve, ll]) => {
      const e = PORCVE.get(cve);
      const p = e ? projection(ll) : null;
      if (!e || !p) return "";
      return `<text x="${p[0].toFixed(1)}" y="${p[1].toFixed(1)}" text-anchor="middle" dominant-baseline="central" font-size="${fontSize}" fill="${colorEtiqueta}" font-family="sans-serif">${esc(texto(e))}</text>`;
    }).join("");
  }
  const bg = background ? `<rect width="${width}" height="${height}" fill="${background}"/>` : "";
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="${esc(titulo)}"><title>${esc(titulo)}</title>${bg}${paths}${labels}</svg>`;
}
var TILE = 54;
var GAP = 6;
function textoContraste(fill) {
  const n = parseInt(fill.slice(1), 16);
  const lum = 0.299 * (n >> 16 & 255) + 0.587 * (n >> 8 & 255) + 0.114 * (n & 255);
  return lum > 150 ? "#1f2937" : "#ffffff";
}
function mosaicoSVG(opts = {}) {
  const {
    data,
    categorias,
    paleta,
    colorRange,
    paletaCategorica = PALETA_CATEGORICA,
    emptyColor = "#e5e7eb",
    mostrarValor = true,
    formatValue,
    background,
    titulo = "Cartograma de mosaicos de M\xE9xico"
  } = opts;
  const cols = resuelvePaleta(paleta, colorRange);
  const colorCat = categorias ? coloresCategorias(categorias, paletaCategorica) : null;
  const vals = data ? Object.values(data).filter((v) => Number.isFinite(v)) : [];
  const min = vals.length ? Math.min(...vals) : 0;
  const max = vals.length ? Math.max(...vals) : 0;
  const fill = (cve) => {
    if (colorCat) {
      const c = categorias?.[cve];
      return (c != null ? colorCat.get(c) : void 0) ?? emptyColor;
    }
    const v = data?.[cve];
    if (v == null || !Number.isFinite(v)) return emptyColor;
    const t = max > min ? (v - min) / (max - min) : 1;
    return interpolaPaleta(cols, t);
  };
  const paso = TILE + GAP;
  const width = MOSAICO_COLUMNAS * paso - GAP;
  const height = MOSAICO_FILAS * paso - GAP;
  const celdas = ESTADOS.map((e) => {
    const celda = MOSAICO_ESTADOS[e.cve];
    if (!celda) return "";
    const x = celda[0] * paso;
    const y = celda[1] * paso;
    const f = fill(e.cve);
    const tc = textoContraste(f);
    const v = data?.[e.cve];
    const val = v != null && Number.isFinite(v) ? formatValue ? formatValue(v, e) : String(v) : null;
    const abrY = val && mostrarValor ? TILE / 2 - 6 : TILE / 2;
    let t = `<g transform="translate(${x} ${y})" data-cve="${esc(e.cve)}" data-nombre="${esc(e.nombre)}"><rect width="${TILE}" height="${TILE}" rx="7" fill="${f}" stroke="#ffffff" stroke-width="1"/>`;
    t += `<text x="${TILE / 2}" y="${abrY}" text-anchor="middle" dominant-baseline="central" font-size="12" font-weight="600" fill="${tc}" font-family="sans-serif">${esc(e.abreviatura)}</text>`;
    if (val && mostrarValor) {
      t += `<text x="${TILE / 2}" y="${TILE / 2 + 11}" text-anchor="middle" dominant-baseline="central" font-size="9" fill="${tc}" font-family="sans-serif">${esc(val)}</text>`;
    }
    return t + "</g>";
  }).join("");
  const bg = background ? `<rect width="${width}" height="${height}" fill="${background}"/>` : "";
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="${esc(titulo)}"><title>${esc(titulo)}</title>${bg}${celdas}</svg>`;
}

export { mapaSVG, mosaicoSVG };
